// Unconditional certificate. GRH is used ONLY to discover candidate relations.
// Each relation and its full lattice index are checked exactly below.
// Execute all intervals, or set Ranges to a selected subset for separate runs.
Ranges := [ <318,50000>, <50000,1000000>, <1000000,3000000>,
            <3000000,6000000>, <6000000,10000000>,
            <10000000,14000000>, <14000000,17507890> ];
for interval in Ranges do
SetClassGroupBounds("GRH");R<x>:=PolynomialRing(Rationals());K<a>:=NumberField(x^5-660*x^3+70983*x-102060);O:=MaximalOrder(K);
Cl:=ClassGroup(O); FB,B:=FactorBasis(O); M:=RelationMatrix(O); rr:=Eltseq(Relations(O));
assert B eq 318 and #FB eq 63;
assert #rr eq Nrows(M) and Ncols(M) eq #FB;
for i in [1..#rr] do
 assert Type(rr[i]) eq FldOrdElt; I:=ideal<O|rr[i]>; T:=&*[FB[j]^M[i,j]:j in [1..#FB]];
 assert I eq T;
end for;
assert ElementaryDivisors(M) eq [1:j in [1..#FB]];
All:=[]; for q in PrimesUpTo(B-1) do for item in Decomposition(O,q) do if Norm(item[1]) lt B then Append(~All,item[1]); end if; end for; end for; assert forall{I:I in All|I in FB};
print "EXACT_RELATIONS_VERIFIED",#rr; print "LOW_PRIME_COVERAGE",#All,B;
print "MINKOWSKI_BOUND",MinkowskiBound(O);


assert MinkowskiBound(O) eq 17507890;
time FactorBasisVerify(O,interval[1],interval[2]);
print "VERIFIED_INTERVAL",interval[1],interval[2];
end for;

